from lxml import etree
import dialect as D

def build(html_text):
    """HTML sang DOCX (không cần browser)"""
    doc = Document()
    root = D.parse(html_text)
    for el in root.iter():
        if el.tag in ("h1", "h2", "h3", "h4"):
            lvl = int(el.tag[1])
            doc.add_heading("".join(el.itertext()), level=lvl)
        elif el.tag == "p":
            p = doc.add_paragraph()
            for text, b, i in D.paragraphs(el)[0]:
                run = p.add_run(text)
                run.bold, run.italic = b, i
        elif el.tag == "ul":
            for li in el.findall("li"):
                p = doc.add_paragraph(style='List Bullet')
                for text, b, i in D.paragraphs(li)[0]:
                    run = p.add_run(text)
                    run.bold, run.italic = b, i
        elif el.tag == "ol":
            for li in el.findall("li"):
                p = doc.add_paragraph(style='List Number')
                for text, b, i in D.paragraphs(li)[0]:
                    run = p.add_run(text)
                    run.bold, run.italic = b, i
        elif el.tag == "table":
            rows = el.findall("tr")
            if rows:
                cols = len(rows[0].findall("td") or rows[0].findall("th"))
                table = doc.add_table(rows=len(rows), cols=cols, style="Table Grid")
                for ri, tr in enumerate(rows):
                    cells = tr.findall("td") or tr.findall("th")
                    for ci, c in enumerate(cells):
                        if ci < cols:
                            table.cell(ri, ci).text = "".join(c.itertext())

    out = io.BytesIO()
    doc.save(out)
    return out.getvalue()
